  SELECT MAX(EXPIRY_DATE)
  INTO   V_EXPIRY_DATE
	FROM   PRIVILEGED_IMPORTERS
	WHERE  IMPR_PRIVILEGE_TYPE = 3
	AND    REC_STATUS = 1
	AND    IMPR_NBR = :IMPORTERS.IMPR_NBR;

