IS
   ret         NUMBER;
   v_chk_upd   NUMBER;
   v_msg       VARCHAR2 (500);
   msg_lvl     VARCHAR2 (5);
   MSG_CD      NUMBER;
BEGIN
   ----------------------------------------------------------------------------------------------------
   BEGIN
      msg_lvl := :SYSTEM.message_level;
      :SYSTEM.message_level := '25';
      FORMS_DDL ('COMMIT');
      :SYSTEM.message_level := msg_lvl;
   EXCEPTION
      WHEN OTHERS
      THEN
         NULL;
