PROCEDURE CHK_DUPL_IMP_BRKR IS
	V_VAR_VALUE VARCHAR2(2) := 0;
	V_CHK       NUMBER;
	V_MSG		VARCHAR2(500);
BEGIN
	BEGIN
		SELECT VAR_VALUE
		INTO V_VAR_VALUE
		FROM SC_PORT_SETTING
		WHERE SYSOBJ_ID = 9
